KG42.register("rules-105cbe9db2748961a057edab",{"id":"24-brooklyn_microgrid::v141-c-R002","paper":"24-brooklyn_microgrid","record":{"rule_id":"v141-c-R002","mechanism_id":"v141-a-M01","name":"Demand submission","process_stage":"bidding","market_meaning":"A prosumer or consumer may submit a buy order through its EMTS to the market; the order includes a requested energy quantity and price. Scope: BMG virtual microgrid market; orders for the next trading time slot. Condition: The prosumer or consumer is willing to trade electricity in the next time slot. Consumer buy orders use consumers' maximum price limits for their preferred energy sources. Scope: BMG's currently implemented consumer bidding strategy, described as 'For now' and 'So far'.","independence_rationale":"Relations governed by the approved function bidding.demand under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"BMG virtual microgrid market; orders for the next trading time slot. | BMG's currently implemented consumer bidding strategy, described as 'For now' and 'So far'.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e04","v141-b-g03-e020"]},"x":[],"theta":[],"phi":[{"constraint_id":"v141-c-R002-C001","kind":"procedural","role":"core","statement":"A prosumer or consumer may submit a buy order through its EMTS to the market; the order includes a requested energy quantity and price. Scope: BMG virtual microgrid market; orders for the next trading time slot. Condition: The prosumer or consumer is willing to trade electricity in the next time slot.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e04"]},{"constraint_id":"v141-c-R002-C002","kind":"procedural","role":"core","statement":"Consumer buy orders use consumers' maximum price limits for their preferred energy sources. Scope: BMG's currently implemented consumer bidding strategy, described as 'For now' and 'So far'.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e04","v141-b-g03-e020"]}],"pi":[{"evidence_id":"v141-b-g02-e04","location":{"location_id":"src-d1d75d8eed-p07-c2r3__v141-a-M01-bidding","page":7,"printed_page":null,"section":"4.2 Market mechanism","anchor_text":"g pp y g ensured without the traditional grid. The BMG’s market mechanism is implemented on the Tran","equation_id":null,"figure_id":"Fig. 6","table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"Any prosumer $P_g$ and consumer $C_a$ willing to trade electricity in the next time slot, can submit buy or sell orders via their EMTS (C6) to the market. Any order includes an order quantity and price. The market mechanism (C4) is a closed order book with a time discrete double auction in 15 min time slots. For now, consumers constantly bid their maximum price limit for their preferred energy sources (e.g. local renewable energy). Prosumers bid the minimum price limit that they request for selling their generation on the microgrid market."},{"evidence_id":"v141-b-g03-e020","location":{"location_id":"src-d1d75d8eed-p10-c1r1__v141-a-M01-bidding","page":10,"printed_page":null,"section":"4.3 Evaluation and discussion","anchor_text":"E. Mengelkamp et al. / Applied En Automatic EMTS (C6) are implemented on the TransActive Grid smart ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"example"},"source_text":"So far, the same bidding strategy is implemented for every customer, i.e. bidding the agents’ maximum or minimum price limit for consumers and prosumers, respectively."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":"No source-defined rule-wide variable is available for demand submission: the text describes the procedural act of submitting an order containing a quantity and price, while x_1 and y_1 are only an illustrative example for C_1 without a stated domain or general definition. Domain or unit details for order prices and quantities are supplied elsewhere for the order-book figure and are not sufficient to define this rule's x without extending scope.","empty_theta_reason":"No fixed numeric parameter or constant is specified for this demand-submission rule. The 15-minute slot, clearing price and double-auction parameters belong to the market-clearing/pricing rules, and consumers' maximum price limits are participant-specific bid preferences rather than a quantified rule parameter in the supplied text."},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-matching"],"extras":{"decision_anchor":"bidding.demand","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e04","quote":"Any prosumer $P_g$ and consumer $C_a$ willing to trade electricity in the next time slot, can submit buy or sell orders via their EMTS (C6) to the market. Any order includes an order quantity and price."}],[{"evidence_id":"v141-b-g02-e04","quote":"For now, consumers constantly bid their maximum price limit for their preferred energy sources (e.g. local renewable energy)."},{"evidence_id":"v141-b-g03-e020","quote":"So far, the same bidding strategy is implemented for every customer, i.e. bidding the agents’ maximum or minimum price limit for consumers and prosumers, respectively."}]],"C2_formalization":{"graph_sha256":"d7128ec5f60c1ee3c7cda945933fdaafbba5e8411ec9359a17a5615a6696af6c","applicability":"non_mathematical","reason":"This rule is a procedural bid-submission rule. The supplied source states that a prosumer or consumer may submit a buy order through its EMTS, that an order contains a quantity and price, and that consumers currently bid their maximum price limit for preferred energy sources. It gives no general equation, inequality, objective, coefficient, optimization role, or defined domain for a rule-wide demand-submission variable. The symbols x_1 and y_1 occur only in an illustrative example (consumer C_1 bids x_1 for y_1) and are not defined as general variables; other numerical/mechanism elements such as the 15-minute double auction, clearing price, and matching belong to other frozen rules. Therefore the demand-submission rule is represented procedurally rather than as a mathematical expression.","bindings":[],"revision_requests":[]}},"quarantined_references":[]}});
